#!/bin/sh
# Oracle solution (FR-40). Generated by eval-harvest emit; do not edit by hand.
#
# Verifier/reference-only: this file, and the reference findings it carries, are never placed where
# the evaluated agent can read them. Harbor's oracle agent uploads solution/ to /solution and runs
# this script (agents/oracle.py:105-151). It submits the reference findings as if it were the agent,
# so the reward stack can be proven to respond to a known-good submission (a non-zero coverage_all).
#
# The findings are inlined at emit time rather than read from tests/oracle.json, because in separate
# verifier mode Harbor builds the verifier image from tests/ and uploads nothing at runtime
# (tech-plan.md:489) — so /tests/ does not exist in the agent environment, which is where this script
# runs. Reading it there would fail with FileNotFoundError, so the known-good submission would never
# be made.
set -eu

# The submission is written under the artifacts convention dir (/logs/artifacts), not /logs/agent,
# because that is the one channel Harbor carries from the agent environment into the separate verifier
# (trial.py:706-712 uploads only artifacts_dir; the convention entry re-materializes /logs/artifacts in
# the verifier). A file under /logs/agent never reaches score.py, which then grades an empty
# submission. score.py's _DEFAULT_AGENT_FINDINGS and instruction.md name the same path.
findings_path="${EVAL_HARVEST_AGENT_FINDINGS:-/logs/artifacts/findings.json}"
mkdir -p "$(dirname "$findings_path")"

# The submission: one record per (finding, location) pair — statement, path, line, and severity, the
# four fields score.py consumes. Built at emit time from the same findings tests/oracle.json is
# serialized from, so the two cannot disagree. The payload is a single-line JSON array inside a quoted
# heredoc: the quotes stop the shell expanding it, and json.dumps escapes every newline, so no payload
# byte can close the heredoc early.
python3 - "$findings_path" <<'PY'
import json
import sys

submission = [{"line":265,"path":"src/mysql-mcp-server/awslabs/mysql_mcp_server/mutable_sql_detector.py","severity":"high","statement":"The new statement-start mutating-keyword scan runs on sqlparse output that does not strip a MySQL '#' comment unless a space follows '#', so a prefix like '#x\\n' hides the leading verb: '#x\\nDO GET_LOCK(...)', '#c\\nSHUTDOWN' and '#c\\nSTART REPLICA' are all allowed in read-only mode. The CWE-184 bypass the PR set out to close is still open."},{"line":113,"path":"src/mysql-mcp-server/awslabs/mysql_mcp_server/mutable_sql_detector.py","severity":"medium","statement":"Blocking DO GET_LOCK while SELECT GET_LOCK, RELEASE_LOCK, replication-wait functions and sys_exec/sys_eval still pass makes the guard asymmetric: the read-shaped twin of the targeted threat bypasses it."},{"line":1145,"path":"src/mysql-mcp-server/tests/test_mutable_sql_detector.py","severity":"medium","statement":"The statement-start test matrix varies only the keyword, never comment/whitespace obfuscation for a fixed keyword, so it cannot catch the '#'-comment bypass; add '#', '#x', '# ' and '#'-after-';' cases."},{"line":109,"path":"src/mysql-mcp-server/awslabs/mysql_mcp_server/mutable_sql_detector.py","severity":"low","statement":"USE <db>, CACHE INDEX and LOAD INDEX INTO CACHE are statement-leading state changers that still pass the read-only gate (SET is blocked, USE is not)."},{"line":897,"path":"src/mysql-mcp-server/tests/test_mutable_sql_detector.py","severity":"low","statement":"All new tests call detect_mutating_keywords directly; none proves run_query rejects a new keyword end-to-end on the read-only path, where the security guarantee actually lives."},{"line":141,"path":"src/mysql-mcp-server/awslabs/mysql_mcp_server/mutable_sql_detector.py","severity":"low","statement":"A ';' inside a string literal trips the anchored statement-start scan (e.g. WHERE note = 'do it; commit later' reports COMMIT), so the no-false-positive guarantee silently depends on the stacked-queries rule and the logged rejection reason is wrong."}]
with open(sys.argv[1], "w", encoding="utf-8") as handle:
    json.dump(submission, handle)
PY
